mapper.select:
SELECT tab.*
FROM (
    SELECT t.id AS 'objectId', t.name AS 'objectName', 10 AS 'objectType' FROM zt_task t WHERE t.id = #{objectId}
  UNION
    SELECT b.id AS 'objectId', b.title AS 'objectName', 20 AS 'objectType' FROM zt_bug b WHERE b.id = #{objectId}
  UNION
    SELECT s.id AS 'objectId', s.title AS 'objectName', 30 AS 'objectType' FROM zt_story s WHERE s.id = #{objectId}
  UNION
    SELECT c.id AS 'objectId', c.title AS 'objectName', 40 AS 'objectType' FROM zt_case c WHERE c.id = #{objectId}
) tab
ORDER BY tab.objectType

mapper.sql:
SELECT t.id AS 'objectId', 10 AS 'objectType', t.name AS 'objectName', t.openedDate AS 'savedate', t.module
FROM zt_task t WHERE 1 = 1 AND t.deleted = '0'
AND t.id = #{objectId}

    AND t.name LIKE CONCAT('%', #{keyword},'%')
    AND t.openedDate > #{dateStart,jdbcType=TIMESTAMP} AND t.openedDate < #{dateEnd,jdbcType=TIMESTAMP}

UNION ALL
SELECT b.id AS 'objectId', 20 AS 'objectType', b.title AS 'objectName', b.openedDate AS 'savedate', b.module
FROM zt_bug b WHERE 1 = 1 AND b.deleted = '0'
AND b.id = #{objectId}

    AND b.title LIKE CONCAT('%', #{keyword},'%')
    AND b.openedDate > #{dateStart,jdbcType=TIMESTAMP} AND b.openedDate < #{dateEnd,jdbcType=TIMESTAMP}

mapper.select:
SELECT tab.* FROM (  ) tab
ORDER BY tab.savedate DESC
LIMIT #{pageStart}, #{pageSize}
